// Execute an r2c plan by providing compatible buffers at call time.
int kind = FUZZ_GET_ATTR_INT(p, "plan_kind");
if (kind != 1) { FUZZ_BAIL(); } // Ensure this is an r2c plan
int real_elems = FUZZ_GET_ATTR_INT(p, "real_elems");
int complex_elems = FUZZ_GET_ATTR_INT(p, "complex_elems");
if (real_elems <= 0 || complex_elems <= 0) { FUZZ_BAIL(); }
// Allocate I/O per recorded sizes
double *in = fftw_alloc_real((size_t)real_elems);
fftw_complex *out = fftw_alloc_complex((size_t)complex_elems);
if (!in || !out) { if (in) fftw_free(in); if (out) fftw_free(out); FUZZ_BAIL(); }
// Execute with supplied arrays; plan must be compatible with contiguous layout
fftw_execute_dft_r2c(*p, in, out);
fftw_free(in);
fftw_free(out);
// Return plan to pool for potential reuse.

// Execute a c2r plan by providing compatible buffers at call time.
int kind = FUZZ_GET_ATTR_INT(p, "plan_kind");
if (kind != 2) { FUZZ_BAIL(); } // Ensure this is a c2r plan
int real_elems = FUZZ_GET_ATTR_INT(p, "real_elems");
int complex_elems = FUZZ_GET_ATTR_INT(p, "complex_elems");
if (real_elems <= 0 || complex_elems <= 0) { FUZZ_BAIL(); }
fftw_complex *in = fftw_alloc_complex((size_t)complex_elems);
double *out = fftw_alloc_real((size_t)real_elems);
if (!in || !out) { if (in) fftw_free(in); if (out) fftw_free(out); FUZZ_BAIL(); }
fftw_execute_dft_c2r(*p, in, out);
fftw_free(in);
fftw_free(out);
// Return plan for reuse.

// Execute a split-format r2c plan with separate output arrays.
int kind = FUZZ_GET_ATTR_INT(p, "plan_kind");
if (kind != 3) { FUZZ_BAIL(); } // Ensure this is a split r2c plan
int real_elems = FUZZ_GET_ATTR_INT(p, "real_elems");
int complex_elems = FUZZ_GET_ATTR_INT(p, "complex_elems");
if (real_elems <= 0 || complex_elems <= 0) { FUZZ_BAIL(); }
double *in = fftw_alloc_real((size_t)real_elems);
double *ro = (double *)fftw_malloc(sizeof(double) * (size_t)complex_elems);
double *io = (double *)fftw_malloc(sizeof(double) * (size_t)complex_elems);
if (!in || !ro || !io) { if (in) fftw_free(in); if (ro) fftw_free(ro); if (io) fftw_free(io); FUZZ_BAIL(); }
fftw_execute_split_dft_r2c(*p, in, ro, io);
fftw_free(in);
fftw_free(ro);
fftw_free(io);
// Return plan for reuse.

