if (!p) { FUZZ_BAIL(); }
// No other references are tracked; assume safe to destroy when selected by the runtime
fftw_destroy_plan(*p);
fftw_free(p);
// After this call, the plan is invalid and the wrapper memory is released.

// Create a guru64 real-to-real plan with small contiguous dimensions and no batching.
int rank = (int)(*FUZZ_PARAM(unsigned int) % 3) + 1; // 1..3 dims
fftw_iodim64 dims[3];
ptrdiff_t nprod = 1;
for (int i = 0; i < rank; ++i) {
    // Keep sizes small to bound allocation and runtime
    ptrdiff_t n = (ptrdiff_t)((*FUZZ_PARAM(unsigned int) % 16) + 1); // 1..16
    dims[i].n = n;
    dims[i].is = (i == 0) ? 1 : nprod; // contiguous layout
    dims[i].os = (i == 0) ? 1 : nprod; // contiguous layout
    nprod *= n;
}
size_t elems = (size_t)nprod;
// Allocate aligned I/O buffers sized for contiguous layout
if (elems == 0 || elems > 2048) { FUZZ_BAIL(); }
double *in = fftw_alloc_real(elems);
double *out = fftw_alloc_real(elems);
if (!in || !out) { if (in) fftw_free(in); if (out) fftw_free(out); FUZZ_BAIL(); }
// Choose per-dimension r2r kinds. Map fuzz values to valid enum range [0,10]
fftw_r2r_kind kind_local[3];
for (int i = 0; i < rank; ++i) {
    kind_local[i] = (fftw_r2r_kind)((int)(*FUZZ_PARAM(unsigned int) % 11));
}
unsigned flags = 0u; // keep planning cheap and deterministic
fftw_plan plan = fftw_plan_guru64_r2r(rank, dims, 0, (const fftw_iodim64 *)nullptr, in, out, kind_local, flags);
fftw_free(in);
fftw_free(out);
if (!plan) { FUZZ_BAIL(); }
// Wrap the opaque plan handle in a managed pointer for the fuzzer object pool
fftw_plan *p = (fftw_plan *)fftw_malloc(sizeof(fftw_plan));
if (!p) { fftw_destroy_plan(plan); FUZZ_BAIL(); }
*p = plan;
// Record attributes for downstream execute stubs
FUZZ_SET_ATTR_INT(p, "plan_kind", 5); // 5 == r2r in existing stubs
FUZZ_SET_ATTR_INT(p, "rank", rank);
FUZZ_SET_ATTR_INT(p, "real_elems", (int)elems);
// Output: p (persistent plan handle)

// Duplicate an existing plan and return a separate wrapper handle.
if (!p) { FUZZ_BAIL(); }
fftw_plan new_plan = fftw_copy_plan(*p);
if (!new_plan) { FUZZ_BAIL(); }
// Allocate wrapper for copied plan
fftw_plan *p_copy = (fftw_plan *)fftw_malloc(sizeof(fftw_plan));
if (!p_copy) { fftw_destroy_plan(new_plan); FUZZ_BAIL(); }
*p_copy = new_plan;
// Propagate attributes from original for execute compatibility
int plan_kind = FUZZ_GET_ATTR_INT(p, "plan_kind");
int rank = FUZZ_GET_ATTR_INT(p, "rank");
int real_elems = FUZZ_GET_ATTR_INT(p, "real_elems");
int complex_elems = FUZZ_GET_ATTR_INT(p, "complex_elems");
int howmany = FUZZ_GET_ATTR_INT(p, "howmany");
if (plan_kind) FUZZ_SET_ATTR_INT(p_copy, "plan_kind", plan_kind);
if (rank) FUZZ_SET_ATTR_INT(p_copy, "rank", rank);
if (real_elems) FUZZ_SET_ATTR_INT(p_copy, "real_elems", real_elems);
if (complex_elems) FUZZ_SET_ATTR_INT(p_copy, "complex_elems", complex_elems);
if (howmany) FUZZ_SET_ATTR_INT(p_copy, "howmany", howmany);
// Outputs: original p (unchanged) and p_copy (independent duplicate)

// Discard accumulated planner wisdom; does not invalidate existing plans.
fftw_forget_wisdom();
// No inputs/outputs; global state only.

// Set a planner time limit. Either disable or set a small positive bound.
double t;
if ((*FUZZ_PARAM(unsigned int) % 2) == 0) {
